import {setArtwork} from './svg-render.js';
import * as conductivity from './conductivity-model.js';
import * as colorimetry from './colorimetry-model.js';
import * as voltaic from './voltaic-model.js';
import {art,wires} from './measurement-art.js';
import {questions,reviewSummary,calibrationGraph} from './measurement-review.js';
import {initializeStorage} from './equipment-storage.js';
import {createEquipmentMenu} from './equipment-menu.js';
import {reviewQuestions,bindReviewQuestions} from './review-questions.js';
const $=id=>document.getElementById(id),bench=$('bench'),layer=$('apparatus'),NS='http://www.w3.org/2000/svg',mode=document.body.dataset.measurement,M={conductivity,colorimetry,voltaic}[mode];
let state=initializeStorage(M.createState()),selected=null,drag=null,wireDrag=null,last=0,note='',menu,controlsMarkup='',dataMarkup='',flowUntil=0;
const groups=new Map();
for(const [id,o] of Object.entries(state.items)){const g=document.createElementNS(NS,'g');g.dataset.id=id;g.classList.add('object');g.setAttribute('role','button');g.setAttribute('tabindex','0');g.setAttribute('aria-label',o.name);g.addEventListener('focus',()=>{if(selected!==id)select(id);});layer.append(g);groups.set(id,g);}
$('equipment').innerHTML=Object.entries(state.items).map(([id,o])=>`<button class="equipment-button" data-equipment="${id}" aria-pressed="false">${o.name}</button>`).join('');
function context(){const o=state.items[selected];if(!M.active(o))return{label:'Select apparatus',buttons:[],disabled:true,hint:'Drag apparatus from Equipment.'};
 if(o.kind==='conductivityMeter')return{label:o.on?'Switch meter off':'Switch meter on',buttons:[['disconnect','Disconnect leads']],hint:'Drag each coloured lead end onto a probe terminal, or select a probe and use its lead buttons.'};
 if(o.kind==='electrode'||o.kind==='metalStrip')return{label:o.parent?'Unclip from vessel':'Clip to vessel rim',buttons:[['red','Connect red lead'],['black','Connect black lead'],...(mode==='conductivity'?[['rinse','Rinse probe']]:[])],hint:mode==='conductivity'?'Clip both probes to the same sample. To rinse: unclip, hold above waste and bring the water beaker nearby.':'Clip each strip near a half-cell. Choose either lead; reversed leads reverse the sign.'};
 if(o.kind==='voltmeter')return{label:o.loaded?'Use high-resistance voltmeter':'Connect 100 Ω load',buttons:[['run','Discharge for 60 s'],['disconnect','Disconnect leads']],hint:'With the load connected, the cell changes while you work. The 60 s action advances model time without a timing challenge.'};
 if(o.kind==='saltBridge')return{label:o.parent?'Remove salt bridge':'Fit salt bridge',buttons:[],hint:'Place the two legs above separate liquid half-cells. Space seats the bridge. The bridge carries ions, not electrons.'};
 if(o.kind==='colorimeter')return{label:o.lid?'Open lid':'Close lid',buttons:[['blank','Set blank']],hint:'Insert a filled cuvette with the lid open. Close the lid and blank with solvent using your chosen filter.'};
 if(o.kind==='cuvette')return{label:o.parent?'Remove cuvette':Math.abs(o.x-state.items.meter.x)<155&&Math.abs(o.y-state.items.meter.y)<140?'Insert cuvette':'Drain above receiver',buttons:[['wipe','Wipe optical faces'],['rotate',o.clearFace?'Turn frosted face to beam':'Turn clear face to beam'],['pour','Drain above receiver']],hint:'Fill at least 2 mL, wipe the faces and insert with the lid open. Draining leaves a 0.05 mL film; rinse by adding water and draining again.'};
 return{label:o.water>0?`Pour ${$('dose').value} mL`:'Pour solid portion',buttons:[],hint:'Hold above a receiving opening and press Space. Each press transfers one portion. The labelled supplied concentration changes if you mix or dilute the contents.'};
}
function renderData(){const signature=JSON.stringify([state.records,state.unknownReadings,state.filter]);if(signature===dataMarkup)return;dataMarkup=signature;
 const rows=mode==='colorimetry'?[...state.records,...state.unknownReadings].sort((a,b)=>a.time-b.time):state.records;
 if(mode==='colorimetry'){$('measurements-head').innerHTML='<tr><th>Sample</th><th>Entered c / mol dm⁻³</th><th>A</th><th>Filter</th><th>Conditions</th></tr>';$('measurements').innerHTML=rows.map(r=>`<tr><td>${escape(r.label)}</td><td>${r.concentration??'Unknown'}</td><td>${r.absorbance.toFixed(3)}</td><td>${r.filter}</td><td>${r.clean?'Wiped':'Fingerprints'} · ${r.clearFace?'Clear face':'Frosted face'} · ${r.lid?'Closed':'Open'} lid${r.blankFilter!==r.filter?' · blank/filter mismatch':''}</td></tr>`).join('');$('plot').innerHTML=calibrationGraph(state);const e=colorimetry.estimate(state);$('data-summary').textContent=e?`Unknown estimate: ${e.value.toPrecision(5)} mol dm⁻³ · ${state.unknownReadings.at(-1).filter} filter${e.extrapolated?' · outside calibration range':''}.`:'No calibration estimate yet.';}
 else if(mode==='conductivity'){$('measurements-head').innerHTML='<tr><th>Sample label</th><th>G / mS</th><th>Cell constant / cm⁻¹</th><th>Volume / mL</th></tr>';$('measurements').innerHTML=rows.map(r=>`<tr><td>${r.name}</td><td>${conductivity.formatConductance(r.value)}</td><td>${r.cellConstant===null?'—':r.cellConstant.toFixed(4)}</td><td>${r.volume.toFixed(2)}</td></tr>`).join('');}
 else{$('measurements-head').innerHTML='<tr><th>Time / s</th><th>V</th><th>I / mA</th><th>Zinc / g</th><th>Cu gained / mg</th><th>Circuit</th></tr>';$('measurements').innerHTML=rows.map(r=>`<tr><td>${r.time.toFixed(1)}</td><td>${r.voltage.toFixed(3)}</td><td>${r.current.toFixed(3)}</td><td>${r.zincMass.toFixed(6)}</td><td>${(r.copperGain*1000).toFixed(4)}</td><td>${r.loaded?'Loaded':'Voltmeter'} · ${r.bridge?'Bridge connected':'Bridge open'}</td></tr>`).join('');}
}
function escape(v){return v.replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;');}
function render(){const r=M.reading(state);
 for(const [id,g]of groups){const o=state.items[id];g.setAttribute('transform',`translate(${o.x} ${o.y}) rotate(${o.angle||0})`);setArtwork(g,art(o,state,r));g.classList.toggle('selected',id===selected);}
 if(selected)layer.append(groups.get(selected));for(const [id,o] of Object.entries(state.items))if(o.parent)layer.append(groups.get(id));
 $('cables').innerHTML=wires(state,'cables');$('wires').innerHTML=wires(state,'ends');$('streams').innerHTML=performance.now()<flowUntil?state.flow.map(f=>`<path d="M${f.from.x} ${f.from.y}L${f.to.x} ${f.to.y}" fill="none" stroke="${f.solid?'#d9c79c':'#7db9c7'}" stroke-width="4" stroke-dasharray="5 3"/>`).join(''):'';
 $('spills').innerHTML=state.spills.map(p=>`<ellipse cx="${p.x}" cy="523" rx="${Math.min(60,7+p.water)}" ry="5" fill="${p.water>0?'#86bdcc':'#e6dec3'}"/>`).join('');
 const c=context(),o=state.items[selected];$('selected-name').textContent=o?.name||'Nothing selected';$('action').textContent=c.label;$('action').disabled=state.phase!=='working'||c.disabled;
 const markup=c.buttons.map(([id,label])=>`<button class="secondary" data-command="${id}" ${state.phase!=='working'?'disabled':''}>${label}</button>`).join('');if(markup!==controlsMarkup){$('fine-controls').innerHTML=markup;controlsMarkup=markup;}$('action-note').textContent=note||c.hint;
 $('live-reading').textContent=mode==='voltaic'?`${r.voltage===null?'—':r.voltage.toFixed(3)} V · ${(r.current*1000).toFixed(3)} mA`:mode==='colorimetry'?`A = ${r.value===null?'—':r.value.toFixed(3)}`:`${r.value===null?'—':conductivity.formatConductance(r.value)} mS`;
 $('instrument-status').textContent=r.status;
 $('instrument').innerHTML=o?.solutes?`<p>${o.water.toFixed(2)} mL${o.kind==='electrode'?' carried film':''}${o.solidNaCl>0?' · undissolved salt':''}</p>`:o?.kind==='metalStrip'?`<p>Remaining metal: ${(o.metalMoles*(o.metal==='Zn'?voltaic.CELL.zincMass:voltaic.CELL.copperMass)).toFixed(6)} g${o.plated>0?` · Cu deposited ${(o.plated*voltaic.CELL.copperMass*1000).toFixed(4)} mg`:''}</p>`:'';
 $('record').disabled=state.phase!=='working';$('clear-records').disabled=state.phase!=='working';$('finish').disabled=state.phase!=='working';for(const b of $('equipment').children){b.disabled=state.phase!=='working';b.setAttribute('aria-pressed',String(b.dataset.equipment===selected));}if(mode==='colorimetry')for(const id of ['filter','record-standard','known-concentration','sample-label'])$(id).disabled=state.phase!=='working';renderData();menu?.sync();
}
function select(id){if(state.phase!=='working')return;selected=id;note='';render();}
const coords=e=>new DOMPoint(e.clientX,e.clientY).matrixTransform(bench.getScreenCTM().inverse());
bench.addEventListener('pointerdown',e=>{if(e.button!==0||state.phase!=='working')return;const lead=e.target.closest('[data-lead]')?.dataset.lead;if(lead){wireDrag=lead;M.connectLead(state,lead,null);const p=coords(e);state.looseEnds[lead]={x:p.x,y:p.y};bench.setPointerCapture(e.pointerId);e.preventDefault();render();return;}const id=e.target.closest('[data-id]')?.dataset.id;if(!id)return;select(id);const p=coords(e),o=state.items[id];drag={id,start:p,dx:p.x-o.x,dy:p.y-o.y,active:false};bench.focus({preventScroll:true});bench.setPointerCapture(e.pointerId);e.preventDefault();});
bench.addEventListener('pointermove',e=>{if(wireDrag){const p=coords(e);state.looseEnds[wireDrag]={x:p.x,y:p.y};render();return;}if(!drag)return;const p=coords(e);if(!drag.active){if(Math.hypot(p.x-drag.start.x,p.y-drag.start.y)<4)return;M.detach(state,drag.id);drag.active=true;}M.physicsFor(state).moveHeld(drag.id,Math.max(65,Math.min(935,p.x-drag.dx)),Math.max(15,Math.min(510,p.y-drag.dy)));render();});
function release(e){if(wireDrag){if(e){const p=coords(e),target=Object.values(state.items).filter(o=>M.active(o)&&['electrode','metalStrip'].includes(o.kind)).sort((a,b)=>Math.hypot(a.x-p.x,a.y-p.y)-Math.hypot(b.x-p.x,b.y-p.y))[0];if(target&&Math.hypot(target.x-p.x,target.y-p.y)<50)M.connectLead(state,wireDrag,target.id);}wireDrag=null;render();return;}if(!drag)return;if(drag.active&&menu?.wantsStore(e)&&menu.store(drag.id))selected=null;else if(drag.active)M.placeItem(state);drag=null;render();}
bench.addEventListener('pointerup',release);bench.addEventListener('pointercancel',()=>{wireDrag=null;release();});
function unclip(o){o.parent=null;if(o.kind==='saltBridge')o.targets=null;o.y-=45;M.physicsFor(state).sync();}
function action(command='normal'){if(state.phase!=='working')return;const o=state.items[selected];if(!M.active(o))return;note='';state.flow=[];
 if(command==='red'||command==='black'){M.connectLead(state,command,o.id);note=`${command} lead connected.`;}
 else if(command==='disconnect'){state.leads={red:null,black:null};note='Leads disconnected.';}
 else if(o.kind==='conductivityMeter'){o.on=!o.on;note=o.on?'Meter on.':'Meter off.';}
 else if(o.kind==='voltmeter'){if(command==='run'){const before=state.charge;voltaic.stepChemistry(state,60);note=state.charge>before?'Advanced 60 s of discharge.':'Advanced 60 s; no sustained external current. Check the load, bridge and leads.';}else{o.loaded=!o.loaded;note=o.loaded?'100 Ω load connected.':'High-resistance voltmeter selected.';}}
 else if(o.kind==='electrode'||o.kind==='metalStrip'){if(command==='rinse')note=conductivity.rinse(state,o.id)?'Probe film washed into the waste vessel.':'Unclip the probe, hold above waste and bring the water beaker nearby.';else if(o.parent){unclip(o);note='Unclipped. Move to another sample.';}else note=M.clip(state,o.id)?'Clipped to vessel rim.':'Move the tip near the vessel opening.';}
 else if(o.kind==='saltBridge'){if(o.parent){unclip(o);note='Bridge removed.';}else note=voltaic.fitBridge(state)?'Salt bridge seated.':'Place the legs above two separate liquid vessels.';}
 else if(o.kind==='colorimeter'){if(command==='blank')note=colorimetry.blank(state)?'Optical blank recorded.':'Insert a filled cuvette before blanking.';else{o.lid=!o.lid;note=o.lid?'Lid closed.':'Lid open.';}}
 else if(o.kind==='cuvette'){if(command==='wipe'){o.clean=true;note='Optical faces wiped.';}else if(command==='rotate'){o.clearFace=!o.clearFace;note=o.clearFace?'Clear face toward beam.':'Frosted face toward beam.';}else if(command==='pour')note=M.pour(state,o.id,4)>0?'Drained one portion; a wet film remains.':'Remove the cuvette and hold above an open receiver.';else if(o.parent)note=colorimetry.remove(state)?'Cuvette removed.':'Open the lid before removing the cuvette.';else if(command==='insert'||Math.abs(o.x-state.items.meter.x)<155&&Math.abs(o.y-state.items.meter.y)<140)note=colorimetry.insert(state,o.id)?'Cuvette inserted.':'Open the lid, clear the existing cuvette and move near the sample well.';else note=M.pour(state,o.id,4)>0?'Drained one portion; a wet film remains.':'Hold above an open receiver, or move near the colorimeter to insert.';}
 else note=M.pour(state,o.id,Number($('dose').value))>0?'One portion transferred.':'Hold above an open receiving vessel.';
 if(state.flow.length)flowUntil=performance.now()+500;render();}
$('action').addEventListener('click',()=>action());$('fine-controls').addEventListener('click',e=>{const c=e.target.closest('[data-command]')?.dataset.command;if(c)action(c);});$('dose').addEventListener('change',render);
$('equipment').addEventListener('click',e=>{const id=e.target.closest('[data-equipment]')?.dataset.equipment;if(id)select(id);});$('equipment').addEventListener('focusin',e=>{const id=e.target.closest('[data-equipment]')?.dataset.equipment;if(id&&id!==selected)select(id);});
document.addEventListener('keydown',e=>{if(e.code!=='Space'||state.phase!=='working'||e.repeat)return;const c=e.target.closest?.('button,input,select,textarea');if(c&&c.id!=='action'&&!c.dataset.equipment)return;e.preventDefault();action();});
function record(type){const row=mode==='colorimetry'?colorimetry.record(state,type,$('known-concentration').value,$('sample-label').value):M.record(state);note=row?'Reading recorded below the bench.':mode==='colorimetry'?'Fill, blank and measure a cuvette; enter a finite non-negative concentration for a standard.':'Complete a valid measurement before recording.';render();}
$('record').addEventListener('click',()=>record('unknown'));
if(mode==='colorimetry'){$('filter').addEventListener('change',e=>{state.filter=e.target.value;note='Filter changed. Check your blank.';render();});$('record-standard').addEventListener('click',()=>record('standard'));}
$('clear-records').addEventListener('click',()=>{if(state.phase!=='working')return;state.records=[];if(state.unknownReadings)state.unknownReadings=[];render();});
$('restart').addEventListener('click',()=>{state=initializeStorage(M.createState());selected=null;drag=null;wireDrag=null;note='';dataMarkup='';flowUntil=0;if(mode==='colorimetry'){$('filter').value='red';$('known-concentration').value='';$('sample-label').value='';}$('result').hidden=true;$('result').innerHTML='';render();});
$('finish').addEventListener('click',()=>{release();state.phase='finished';render();const q=questions(state),p=$('result');p.hidden=false;p.innerHTML=`<h2>Review your ${mode==='voltaic'?'voltaic cell':mode} investigation</h2>${reviewSummary(state)}${reviewQuestions(mode,q)}`;bindReviewQuestions(mode,()=>{state.phase='complete';},q);p.focus({preventScroll:true});p.scrollIntoView({behavior:'smooth',block:'nearest'});});
function frame(time){const dt=Math.min(.05,(time-last)/1000);last=time;if(state.phase==='working'){M.stepPhysics(state,dt,drag?.active?drag.id:null);M.stepChemistry(state,dt);render();}requestAnimationFrame(frame);}
menu=createEquipmentMenu({getState:()=>state,world:()=>M.physicsFor(state),groups,select,begin(id){select(id);M.detach(state,id);drag={id,dx:0,dy:0,active:true};},end:release,render,isDragging:()=>Boolean(drag?.active)});render();requestAnimationFrame(frame);
